/**
 * Reading text out of an image or a PDF, on the device.
 *
 * Two engines, and which one runs matters:
 *
 *   1. **A PDF with a text layer needs no OCR at all.** Most invoices, bank
 *      statements, e-tickets and BPJS letters already carry their text; pdf.js
 *      hands it over exactly, instantly, with no recognition error possible.
 *      Running OCR over those would be slower *and* less accurate, which is the
 *      mistake most "scan anything" features make.
 *   2. **Photos and scanned PDFs go to Tesseract** (WASM, Indonesian trained
 *      data), which runs entirely in the browser.
 *
 * Nothing is uploaded. There is no OCR API here, no key, no per-page cost —
 * which is also why the accuracy ceiling is Tesseract's rather than a cloud
 * vision model's, and the UI says so instead of promising more.
 *
 * The engine, the worker and the Indonesian language data come to ~5 MB,
 * fetched the first time this screen is used and cached after that. They are
 * served from this app's own origin, not a CDN, so the promise that nothing
 * leaves the device survives the feature. Three core builds are vendored
 * because browsers differ in the SIMD they support; exactly one is downloaded.
 */

export type OcrStage = 'siap' | 'memuat' | 'membaca' | 'selesai' | 'gagal'

export interface OcrProgress {
  stage: OcrStage
  /** 0–1 within the current stage, or null when it cannot be known. */
  ratio: number | null
  /** For multi-page PDFs. */
  page?: number
  pages?: number
}

export interface OcrResult {
  text: string
  /** How the text was obtained — the UI shows this, because it changes trust. */
  source: 'pdf-text' | 'ocr'
  pages: number
}

/**
 * Where the engine files live.
 *
 * Normally the app's own origin. The APK is the exception: it runs from
 * `file://`, where these files are not bundled (they would add ~7 MB to a
 * 0.6 MB download), so it falls back to the published copy. That fallback is a
 * network fetch, which is why it is only ever reached after the local one 404s.
 */
/**
 * Absolute, not root-relative, and that is not a style choice.
 *
 * The engine loads inside a Web Worker created from a blob. A blob worker has
 * no meaningful base URL, so a path like `/ocr/core.js` gives its internal
 * `locateFile` nothing to resolve the sibling `.wasm` against — it throws
 * "Failed to parse URL" and the screen sits on "nyiapin mesin baca" forever.
 * An absolute URL resolves from anywhere.
 */
const LOCAL_BASE = new URL(`${import.meta.env.BASE_URL}ocr/`, location.href).href
const PUBLISHED_BASE = 'https://meriaworks.github.io/temudua/app/ocr/'

let baseCache: string | null = null

export async function ocrBase(): Promise<string> {
  if (baseCache) return baseCache
  try {
    const res = await fetch(`${LOCAL_BASE}worker.min.js`, { method: 'HEAD' })
    baseCache = res.ok ? LOCAL_BASE : PUBLISHED_BASE
  } catch {
    baseCache = PUBLISHED_BASE
  }
  return baseCache
}

/** Text already inside a PDF, if it has any worth having. */
async function pdfText(
  file: File,
  onProgress: (p: OcrProgress) => void,
): Promise<{ text: string; pages: number; images: HTMLCanvasElement[] }> {
  const pdfjs = await import('pdfjs-dist')
  // The worker ships with the package; pointing at it with `new URL` lets the
  // bundler fingerprint and serve it instead of reaching for a CDN.
  pdfjs.GlobalWorkerOptions.workerSrc = new URL(
    'pdfjs-dist/build/pdf.worker.min.mjs',
    import.meta.url,
  ).toString()

  const doc = await pdfjs.getDocument({ data: await file.arrayBuffer() }).promise
  const parts: string[] = []
  const images: HTMLCanvasElement[] = []

  for (let i = 1; i <= doc.numPages; i++) {
    onProgress({ stage: 'membaca', ratio: i / doc.numPages, page: i, pages: doc.numPages })
    const page = await doc.getPage(i)
    const content = await page.getTextContent()
    const line = content.items
      .map((it) => ('str' in it ? it.str : ''))
      .join(' ')
      .replace(/\s+/g, ' ')
      .trim()
    parts.push(line)

    // Rendered as well, because a page with no text layer has to go to OCR and
    // re-opening the document to rasterise it later doubles the work.
    if (line.length < 20) {
      const viewport = page.getViewport({ scale: 2 })
      const canvas = document.createElement('canvas')
      canvas.width = viewport.width
      canvas.height = viewport.height
      const ctx = canvas.getContext('2d')
      if (ctx) {
        await page.render({ canvasContext: ctx, viewport }).promise
        images.push(canvas)
      }
    }
  }
  return { text: parts.join('\n\n').trim(), pages: doc.numPages, images }
}

/** Tesseract over one or more images. */
async function recognise(
  sources: (File | HTMLCanvasElement)[],
  onProgress: (p: OcrProgress) => void,
): Promise<string> {
  const base = await ocrBase()
  const { createWorker } = await import('tesseract.js')

  onProgress({ stage: 'memuat', ratio: null })
  const worker = await createWorker('ind', 1, {
    workerPath: `${base}worker.min.js`,
    // The directory, not one file inside it. Naming a single core looks
    // tidier and does not work: the emscripten loader then resolves its own
    // `.wasm` against nothing and dies inside the worker. Given the folder,
    // tesseract.js picks the variant this browser supports and hands the
    // loader absolute paths for both halves — so all three LSTM variants are
    // vendored, and only the ~2.7 MB one that gets picked is ever downloaded.
    corePath: base,
    langPath: base,
    // Fetching the language data is the slow part on a first run, and a bar
    // that does not move is how people conclude the feature is broken.
    logger: (m: { status: string; progress: number }) => {
      if (m.status === 'recognizing text') onProgress({ stage: 'membaca', ratio: m.progress })
      else onProgress({ stage: 'memuat', ratio: m.progress || null })
    },
  })

  try {
    const out: string[] = []
    for (let i = 0; i < sources.length; i++) {
      onProgress({ stage: 'membaca', ratio: null, page: i + 1, pages: sources.length })
      const { data } = await worker.recognize(sources[i]!)
      out.push(data.text.trim())
    }
    return out.join('\n\n').trim()
  } finally {
    // Always terminated: a leaked worker holds tens of megabytes of WASM heap.
    await worker.terminate()
  }
}

export async function readFile(
  file: File,
  onProgress: (p: OcrProgress) => void = () => {},
): Promise<OcrResult> {
  const isPdf = file.type === 'application/pdf' || /\.pdf$/i.test(file.name)

  if (isPdf) {
    const { text, pages, images } = await pdfText(file, onProgress)
    // 20 characters per page is the line between "this PDF has text" and "this
    // PDF is a photo of a document with a stray page number on it".
    if (text.replace(/\s/g, '').length >= pages * 20) {
      onProgress({ stage: 'selesai', ratio: 1 })
      return { text, source: 'pdf-text', pages }
    }
    const scanned = await recognise(images.length ? images : [], onProgress)
    onProgress({ stage: 'selesai', ratio: 1 })
    return { text: [text, scanned].filter(Boolean).join('\n\n').trim(), source: 'ocr', pages }
  }

  const text = await recognise([file], onProgress)
  onProgress({ stage: 'selesai', ratio: 1 })
  return { text, source: 'ocr', pages: 1 }
}
