import { useRef, useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { Card, Field } from '@/components/ui'
import { Icon } from '@/design-system/Icon'
import { useI18n } from '@/i18n'
import { formatRupiah, fmtDate } from '@/i18n/format'
import { readFile, type OcrProgress, type OcrResult } from './ocr'
import { readReceipt, type ReceiptRead } from './receipt'
import './scan.css'

/**
 * Scan — a photo or a PDF turned into text, on the device.
 *
 * The screen is shaped around the case that actually happens: someone
 * photographs a struk and wants the amount in the book without typing it. So
 * the parsed total, date and shop are shown first, as fields you can correct,
 * and the raw text is underneath for everything else — a letter, an invoice, a
 * page of a contract.
 *
 * Two honesty rules here. The result always says whether the text was *read*
 * out of a PDF or *recognised* from pixels, because those two have very
 * different error rates. And a parsed number is always shown in an editable
 * field, never written straight into the ledger: OCR misreads, and a couple's
 * money is the last place to find that out later.
 */
export default function Scan() {
  const { t, locale } = useI18n()
  const navigate = useNavigate()
  const fileRef = useRef<HTMLInputElement>(null)
  const cameraRef = useRef<HTMLInputElement>(null)

  const [busy, setBusy] = useState(false)
  const [progress, setProgress] = useState<OcrProgress>({ stage: 'siap', ratio: null })
  const [result, setResult] = useState<OcrResult | null>(null)
  const [parsed, setParsed] = useState<ReceiptRead | null>(null)
  const [error, setError] = useState<string | null>(null)
  const [amount, setAmount] = useState('')
  const [label, setLabel] = useState('')
  const [date, setDate] = useState('')

  async function run(file: File | undefined) {
    if (!file || busy) return
    setBusy(true)
    setError(null)
    setResult(null)
    setParsed(null)
    try {
      const out = await readFile(file, setProgress)
      setResult(out)
      const r = readReceipt(out.text)
      setParsed(r)
      setAmount(r.total ? String(r.total) : '')
      setLabel(r.merchant ?? '')
      setDate(r.date ?? new Date().toISOString().slice(0, 10))
    } catch (e) {
      // One message for every failure: a wrong file, a corrupt PDF and a
      // failed engine download all mean the same thing to the person holding
      // the phone — try again or type it. The technical reason goes to the
      // console as a warning, because "it just says nggak kebaca" is
      // impossible to debug from a bug report.
      console.warn('[scan]', e)
      setError(t('scan.failed'))
      setProgress({ stage: 'gagal', ratio: null })
    } finally {
      setBusy(false)
    }
  }

  /** Hands the parsed figures to the money screen; it does the writing. */
  function toExpense() {
    const params = new URLSearchParams({ jumlah: amount, ket: label, tgl: date })
    navigate(`/uang?scan=${encodeURIComponent(params.toString())}`)
  }

  const pct = progress.ratio === null ? null : Math.round(progress.ratio * 100)

  return (
    <div className="stack">
      <h1>{t('scan.title')}</h1>
      <p className="card__hint">{t('scan.subtitle')}</p>

      <Card title={t('scan.pick')} icon="export" hint={t('scan.pickHint')}>
        <div className="stack stack--tight">
          <button
            type="button"
            className="btn btn--block"
            disabled={busy}
            onClick={() => cameraRef.current?.click()}
          >
            <Icon name="scan" size={18} />
            {t('scan.camera')}
          </button>
          <button
            type="button"
            className="btn btn--ghost btn--block"
            disabled={busy}
            onClick={() => fileRef.current?.click()}
          >
            <Icon name="export" size={18} />
            {t('scan.file')}
          </button>
          <input
            ref={cameraRef}
            type="file"
            accept="image/*"
            capture="environment"
            hidden
            onChange={(e) => void run(e.target.files?.[0])}
          />
          <input
            ref={fileRef}
            type="file"
            accept="image/*,application/pdf"
            hidden
            onChange={(e) => void run(e.target.files?.[0])}
          />
          <p className="disclaimer">{t('scan.privacy')}</p>
        </div>
      </Card>

      {busy && (
        <Card title={t(`scan.stage.${progress.stage}`)} icon="info">
          <div className="stack stack--tight">
            <div
              className="scanbar"
              role="progressbar"
              aria-valuemin={0}
              aria-valuemax={100}
              aria-valuenow={pct ?? undefined}
              aria-label={t(`scan.stage.${progress.stage}`)}
            >
              <i style={pct === null ? undefined : { width: `${pct}%` }} className={pct === null ? 'scanbar__i scanbar__i--idle' : 'scanbar__i'} />
            </div>
            <p className="card__hint">
              {progress.pages && progress.pages > 1
                ? t('scan.page', { n: progress.page ?? 1, total: progress.pages })
                : t('scan.firstRun')}
            </p>
          </div>
        </Card>
      )}

      {error && (
        <p className="banner banner--danger" role="alert">
          {error}
        </p>
      )}

      {parsed && result && (
        <Card title={t('scan.found')} icon="money" hint={t('scan.foundHint')}>
          <div className="stack stack--tight">
            <Field label={t('scan.amount')} hint={parsed.totalLabel ? t('scan.fromLabel', { label: parsed.totalLabel.toUpperCase() }) : t('scan.noTotal')}>
              {(p) => (
                <input
                  {...p}
                  type="text"
                  inputMode="numeric"
                  value={amount}
                  onChange={(e) => setAmount(e.target.value.replace(/\D+/g, ''))}
                />
              )}
            </Field>
            {amount && <p className="scanamt">{formatRupiah(Number(amount), locale)}</p>}

            <Field label={t('scan.merchant')}>
              {(p) => <input {...p} type="text" value={label} onChange={(e) => setLabel(e.target.value)} />}
            </Field>
            <Field label={t('scan.date')}>
              {(p) => <input {...p} type="date" value={date} onChange={(e) => setDate(e.target.value)} />}
            </Field>

            <button type="button" className="btn btn--block" disabled={!amount} onClick={toExpense}>
              <Icon name="money" size={18} />
              {t('scan.toExpense')}
            </button>
            <p className="card__hint">{t('scan.checkFirst')}</p>
          </div>
        </Card>
      )}

      {result && (
        <Card
          title={t('scan.text')}
          icon="tasks"
          hint={t(result.source === 'pdf-text' ? 'scan.srcPdf' : 'scan.srcOcr')}
        >
          <div className="stack stack--tight">
            <textarea
              className="scantext"
              rows={12}
              value={result.text}
              readOnly
              aria-label={t('scan.text')}
            />
            <button
              type="button"
              className="btn btn--ghost btn--block"
              onClick={() => void navigator.clipboard?.writeText(result.text).catch(() => {})}
            >
              <Icon name="export" size={18} />
              {t('scan.copy')}
            </button>
            {result.pages > 1 && (
              <p className="card__hint">{t('scan.pages', { n: result.pages })}</p>
            )}
            {parsed?.date && (
              <p className="card__hint">
                {t('scan.date')}: {fmtDate(parsed.date, 'd MMMM yyyy', locale)}
              </p>
            )}
          </div>
        </Card>
      )}
    </div>
  )
}
