/**
 * Reading an Indonesian receipt — pure, no React, no OCR engine, no copy.
 *
 * OCR hands back a wall of noisy text. This turns it into the three things a
 * couple actually wants off a struk: how much, when, and where. It is written
 * against how Indonesian receipts are actually printed, not a generic parser:
 *
 *   - The total is labelled `TOTAL`, `JUMLAH`, `TOTAL BELANJA`, `GRAND TOTAL`
 *     or — on a lot of minimarket slips — `TUNAI` / `BAYAR` / `DIBAYAR`. The
 *     last of those is a trap, because `TUNAI` is what the customer *handed
 *     over*, and `KEMBALI`/`KEMBALIAN` is the change. A slip that reads
 *     TOTAL 47.500 / TUNAI 50.000 / KEMBALI 2.500 must yield 47.500, so a
 *     labelled TOTAL always wins over a labelled TUNAI.
 *   - Rupiah is printed `47.500`, `Rp47.500`, `47,500`, `47.500,00` and
 *     `Rp 47.500,-`. The dot is a thousands separator, not a decimal point —
 *     reading it the English way turns forty-seven thousand into forty-seven.
 *   - Dates come as `02/08/26`, `02-08-2026` and `2 Agu 2026`, day first.
 *
 * Everything returns `null` rather than a guess when it is not sure. A wrong
 * amount silently written into a couple's book is worse than an empty field.
 */

export interface ReceiptRead {
  /** Rupiah, as a whole number. Null when no labelled total was found. */
  total: number | null
  /** `yyyy-MM-dd`, or null. */
  date: string | null
  /** Best guess at the shop name — the first usable line. */
  merchant: string | null
  /** Which label produced the total, for the UI to show its work. */
  totalLabel: string | null
}

/** Labels in priority order. Earlier wins, so TOTAL beats TUNAI. */
const TOTAL_LABELS = [
  'grand total',
  'total belanja',
  'total bayar',
  'total harga',
  'total tagihan',
  'total',
  'jumlah bayar',
  'jumlah',
  'subtotal',
  'dibayar',
  'bayar',
  'tunai',
  'cash',
]

/** Never read an amount off these lines. */
const NEVER = /kembali|kembalian|change|hemat|diskon|potongan|ppn|pajak|tax|point|poin|npwp|no\.?\s*hp|telp/i

const MONTHS: Record<string, number> = {
  jan: 1, feb: 2, peb: 2, mar: 3, apr: 4, mei: 5, may: 5, jun: 6, jul: 7,
  agu: 8, ags: 8, aug: 8, sep: 9, okt: 10, oct: 10, nov: 11, des: 12, dec: 12,
}

/**
 * "Rp 47.500,-" → 47500.
 *
 * The rule that matters: a dot or a comma is a decimal separator only when it
 * is followed by exactly two digits *and* those are the last digits on the
 * token. Everything else is a thousands separator.
 */
export function parseRupiah(raw: string): number | null {
  const t = raw.replace(/rp/gi, '').replace(/[^\d.,]/g, '').replace(/[.,]+$/, '')
  if (!/\d/.test(t)) return null
  const decimal = /[.,](\d{2})$/.exec(t)
  const body = decimal ? t.slice(0, -3) : t
  const digits = body.replace(/[.,]/g, '')
  if (!digits) return null
  const n = Number(digits)
  if (!Number.isFinite(n) || n <= 0) return null
  // Receipts do not run to a trillion rupiah; a number that big is OCR noise
  // — a smudged line read as extra digits.
  return n > 999_999_999 ? null : n
}

/** Every money-looking token on a line, largest last. */
function amountsOn(line: string): number[] {
  const out: number[] = []
  for (const m of line.matchAll(/(?:rp\.?\s*)?\d[\d.,]*/gi)) {
    // Four or more bare digits, or any grouped number: prices, not quantities.
    const raw = m[0]
    if (!/[.,]/.test(raw) && raw.replace(/\D/g, '').length < 3) continue
    const n = parseRupiah(raw)
    if (n !== null) out.push(n)
  }
  return out
}

export function findTotal(text: string): { total: number | null; label: string | null } {
  const lines = text.split(/\r?\n/).map((l) => l.trim()).filter(Boolean)

  for (const label of TOTAL_LABELS) {
    for (let i = 0; i < lines.length; i++) {
      const line = lines[i]!
      const low = line.toLowerCase()
      if (!low.includes(label) || NEVER.test(low)) continue
      // `total` also matches `subtotal`; when we are looking for the plain one,
      // skip lines where it only appears as part of a longer word.
      if (label === 'total' && /sub\s*total/.test(low)) continue

      const here = amountsOn(line.slice(low.indexOf(label) + label.length))
      if (here.length) return { total: Math.max(...here), label }
      // Thermal printers wrap the amount onto the next line often enough that
      // ignoring it loses a lot of real receipts.
      const next = lines[i + 1]
      if (next && !NEVER.test(next.toLowerCase())) {
        const below = amountsOn(next)
        if (below.length && !/[a-z]{4,}/i.test(next)) return { total: Math.max(...below), label }
      }
    }
  }
  return { total: null, label: null }
}

export function findDate(text: string, today = new Date()): string | null {
  const pad = (n: number) => String(n).padStart(2, '0')
  const ok = (y: number, m: number, d: number) => {
    if (m < 1 || m > 12 || d < 1 || d > 31) return null
    // A receipt from the future is a misread; so is one from before smartphones.
    if (y < 2000 || y > today.getFullYear() + 1) return null
    return `${y}-${pad(m)}-${pad(d)}`
  }

  // 02/08/2026, 02-08-26, 2.8.2026 — day first, which is how Indonesia prints.
  const numeric = /\b(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{2,4})\b/.exec(text)
  if (numeric) {
    const d = Number(numeric[1])
    const m = Number(numeric[2])
    let y = Number(numeric[3])
    if (y < 100) y += 2000
    const hit = ok(y, m, d)
    if (hit) return hit
  }

  // 2 Agu 2026 / 2 Agustus 2026
  const named = /\b(\d{1,2})\s+([A-Za-z]{3,9})\.?\s+(\d{4})\b/.exec(text)
  if (named) {
    const m = MONTHS[named[2]!.slice(0, 3).toLowerCase()]
    if (m) {
      const hit = ok(Number(named[3]), m, Number(named[1]))
      if (hit) return hit
    }
  }

  // 2026-08-02, printed by some POS systems.
  const iso = /\b(\d{4})-(\d{1,2})-(\d{1,2})\b/.exec(text)
  if (iso) return ok(Number(iso[1]), Number(iso[2]), Number(iso[3]))

  return null
}

export function findMerchant(text: string): string | null {
  for (const raw of text.split(/\r?\n/)) {
    const line = raw.trim()
    if (line.length < 3 || line.length > 40) continue
    // Skip the address, the phone number, the tax id and anything that is
    // mostly digits — the shop name is the first line that reads like a name.
    if (/\d{4,}/.test(line)) continue
    if (/jl\.?|jalan|telp|no\.|npwp|kasir|struk|nota/i.test(line)) continue
    const letters = line.replace(/[^A-Za-z]/g, '').length
    if (letters < 3 || letters / line.length < 0.5) continue
    return line.replace(/\s+/g, ' ')
  }
  return null
}

export function readReceipt(text: string, today = new Date()): ReceiptRead {
  const { total, label } = findTotal(text)
  return {
    total,
    totalLabel: label,
    date: findDate(text, today),
    merchant: findMerchant(text),
  }
}
